    @Test
    void aPercentageDiscountRoundsHalfUpToAMinorUnit() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            String percentOff = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.applyDiscount(percentOff, "12.5");
            assertEquals(Money.pln(875), orders.summary(percentOff).total());

            String halfPercentOff = orders.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));
            orders.applyDiscount(halfPercentOff, "0.5");
            assertEquals(Money.pln(99), orders.summary(halfPercentOff).total());
        }
    }

    @Test
    void aDiscountOutsideZeroToHundredPercentIsRejected() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "101"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "-1"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "abc"));
            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
